import { Hono } from 'hono';

/**
 * Pluggable nonce replay protection store.
 *
 * The facilitator checks this store to prevent replay attacks.
 * Two implementations are shipped: {@link kvNonceStore} for Cloudflare KV
 * and {@link memoryNonceStore} for single-instance deployments.
 * Operators can provide their own implementation (Redis, D1, DynamoDB, etc.).
 */
interface NonceStore {
    /** Returns `true` if the nonce has already been used. */
    has(nonce: string): Promise<boolean>;
    /** Stores a nonce. Implementations should expire entries after `ttlSeconds` (default 86400 = 24h). */
    set(nonce: string, ttlSeconds?: number): Promise<void>;
}

/**
 * EVM chain configuration for the facilitator.
 */
interface EvmConfig {
    /** Hex-encoded private key (0x-prefixed). Used as the gas wallet for settlement transactions. */
    privateKey: string;
    /** Mapping of CAIP-2 network identifier to JSON-RPC URL. */
    rpcUrls: Record<string, string>;
}
/**
 * SVM (Solana) configuration for the facilitator.
 */
interface SvmConfig {
    /** Base58-encoded private key. Used as the fee payer for settlement transactions. */
    privateKey: string;
    /** Mapping of CAIP-2 network identifier to JSON-RPC URL. */
    rpcUrls: Record<string, string>;
}
/**
 * Configuration for the x402 facilitator Hono sub-app.
 *
 * At least one of `evm` or `svm` must be provided. The facilitator will only
 * advertise support for chains that have been configured.
 */
interface FacilitatorConfig {
    /** EVM chain configuration. Omit to disable EVM support. */
    evm?: EvmConfig;
    /** SVM (Solana) chain configuration. Omit to disable Solana support. */
    svm?: SvmConfig;
    /** Pluggable nonce store for replay protection. Defaults to in-memory. */
    nonceStore?: NonceStore;
}

/** Cloudflare KV `KVNamespace` — typed here to avoid a hard runtime dependency. */
interface KVNamespace {
    get(key: string): Promise<string | null>;
    put(key: string, value: string, options?: {
        expirationTtl?: number;
    }): Promise<void>;
}
/**
 * Creates a {@link NonceStore} backed by Cloudflare KV.
 *
 * Nonces are stored with a 24-hour TTL by default.
 *
 * @param kv - A Cloudflare `KVNamespace` binding.
 * @returns A `NonceStore` suitable for distributed, multi-instance deployments.
 *
 * @example
 * ```ts
 * import { x402Facilitator, kvNonceStore } from "@oviato/x402-facilitator-hono";
 *
 * app.route("/facilitator", x402Facilitator({
 *   evm: { privateKey: env.EVM_PRIVATE_KEY, rpcUrls: { "base-sepolia": env.RPC_URL } },
 *   nonceStore: kvNonceStore(env.NONCE_KV),
 * }));
 * ```
 */
declare function kvNonceStore(kv: KVNamespace): NonceStore;

/**
 * Creates a {@link NonceStore} backed by an in-memory `Map`.
 *
 * Nonces are automatically evicted after 24 hours via `setTimeout`.
 * Suitable for single-instance deployments (Node.js, Bun, Deno).
 * For multi-instance or edge deployments, use {@link kvNonceStore} or a custom store.
 *
 * @returns A `NonceStore` backed by an in-memory `Map`.
 *
 * @example
 * ```ts
 * import { x402Facilitator, memoryNonceStore } from "@oviato/x402-facilitator-hono";
 *
 * app.route("/facilitator", x402Facilitator({
 *   evm: { privateKey: env.EVM_PRIVATE_KEY, rpcUrls: { "base-sepolia": env.RPC_URL } },
 *   nonceStore: memoryNonceStore(),
 * }));
 * ```
 */
declare function memoryNonceStore(): NonceStore;

/**
 * Creates a mountable Hono sub-app implementing the x402 facilitator protocol.
 *
 * The returned app exposes three routes:
 * - `GET /supported` — networks and schemes this facilitator supports
 * - `POST /verify` — verify a payment payload against requirements
 * - `POST /settle` — settle a payment on-chain
 *
 * Mount it on any Hono app via `app.route()`:
 *
 * @example
 * ```ts
 * import { Hono } from "hono";
 * import { x402Facilitator } from "@oviato/x402-facilitator-hono";
 *
 * const app = new Hono();
 *
 * app.route("/facilitator", await x402Facilitator({
 *   evm: {
 *     privateKey: env.EVM_PRIVATE_KEY,
 *     rpcUrls: { "eip155:84532": env.RPC_URL_BASE_SEPOLIA },
 *   },
 * }));
 *
 * export default app;
 * ```
 *
 * @param config - Facilitator configuration specifying chains, keys, and optional nonce store.
 * @returns A Hono sub-app with `/supported`, `/verify`, and `/settle` routes.
 */
declare function x402Facilitator(config: FacilitatorConfig): Promise<Hono>;

export { type EvmConfig, type FacilitatorConfig, type NonceStore, type SvmConfig, kvNonceStore, memoryNonceStore, x402Facilitator };
